// Edit the three constants. In a real flow, build EVENT from the nodes before this one.
const SOURCE = 'demo';                              // the source name registered in the hub
const EVENT = { order: 4242, total: 120.5, currency: 'PHP' };
const KEY = `order-${EVENT.order}`;                 // must be the SAME every time this event is sent

const body = JSON.stringify(EVENT);
const timestamp = String(Math.floor(Date.now() / 1000));

// The hub signs timestamp, key and body together, joined by newlines.
return [{ json: { source: SOURCE, key: KEY, timestamp, body, toSign: `${timestamp}\n${KEY}\n${body}` } }];
